-- Script V12 - Estrutura app_ferias usando MATRÍCULA como identificador de negócio
-- Gerado a partir de export_app_ferias.xlsx. Execute no pgAdmin antes de subir a versão V12 do app.

CREATE SCHEMA IF NOT EXISTS app_ferias;
SET search_path TO app_ferias, public;


CREATE TABLE IF NOT EXISTS app_ferias.colaboradores (
    id INTEGER PRIMARY KEY,
    matricula VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(255),
    nome_completo VARCHAR(255) NOT NULL,
    cargo TEXT,
    setor TEXT,
    unidade VARCHAR(100),
    empresa VARCHAR(100),
    telefone VARCHAR(50),
    regime VARCHAR(50),
    data_admissao DATE,
    status VARCHAR(50) DEFAULT 'ATIVO',
    dias_direito INTEGER NOT NULL DEFAULT 0,
    origem_sheet_id VARCHAR(50),
    origem_row_id VARCHAR(50),
    raw_payload JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
ALTER TABLE app_ferias.colaboradores ADD COLUMN IF NOT EXISTS matricula VARCHAR(50);
ALTER TABLE app_ferias.colaboradores ADD COLUMN IF NOT EXISTS empresa VARCHAR(100);
ALTER TABLE app_ferias.colaboradores ADD COLUMN IF NOT EXISTS unidade VARCHAR(100);
ALTER TABLE app_ferias.colaboradores ADD COLUMN IF NOT EXISTS telefone VARCHAR(50);
ALTER TABLE app_ferias.colaboradores ADD COLUMN IF NOT EXISTS dias_direito INTEGER NOT NULL DEFAULT 0;
ALTER TABLE app_ferias.colaboradores ADD COLUMN IF NOT EXISTS origem_sheet_id VARCHAR(50);
ALTER TABLE app_ferias.colaboradores ADD COLUMN IF NOT EXISTS origem_row_id VARCHAR(50);
ALTER TABLE app_ferias.colaboradores ADD COLUMN IF NOT EXISTS raw_payload JSONB DEFAULT '{}'::jsonb;
ALTER TABLE app_ferias.colaboradores ALTER COLUMN cargo TYPE TEXT;
ALTER TABLE app_ferias.colaboradores ALTER COLUMN setor TYPE TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_colaboradores_matricula ON app_ferias.colaboradores (matricula);
CREATE INDEX IF NOT EXISTS ix_colaboradores_email_lower ON app_ferias.colaboradores (lower(email));

CREATE TABLE IF NOT EXISTS app_ferias.permissoes_usuario (
    colaborador_id INTEGER REFERENCES app_ferias.colaboradores(id),
    colaborador_matricula VARCHAR(50) REFERENCES app_ferias.colaboradores(matricula),
    role VARCHAR(20) NOT NULL,
    PRIMARY KEY (colaborador_id, role)
);
ALTER TABLE app_ferias.permissoes_usuario ADD COLUMN IF NOT EXISTS colaborador_matricula VARCHAR(50);
CREATE UNIQUE INDEX IF NOT EXISTS uq_permissoes_usuario_matricula_role ON app_ferias.permissoes_usuario (colaborador_matricula, role);

CREATE TABLE IF NOT EXISTS app_ferias.hierarquia_gestao (
    id SERIAL PRIMARY KEY,
    colaborador_id INTEGER REFERENCES app_ferias.colaboradores(id) UNIQUE,
    colaborador_matricula VARCHAR(50) REFERENCES app_ferias.colaboradores(matricula) UNIQUE,
    gestor_direto_id INTEGER REFERENCES app_ferias.colaboradores(id),
    gestor_direto_matricula VARCHAR(50) REFERENCES app_ferias.colaboradores(matricula),
    gestor_direto_email VARCHAR(255),
    gestor_superior_tipo VARCHAR(20) DEFAULT 'GESTOR',
    gestor_superior_id INTEGER REFERENCES app_ferias.colaboradores(id),
    gestor_superior_matricula VARCHAR(50) REFERENCES app_ferias.colaboradores(matricula),
    gestor_superior_email_custom VARCHAR(255)
);
ALTER TABLE app_ferias.hierarquia_gestao ADD COLUMN IF NOT EXISTS colaborador_matricula VARCHAR(50);
ALTER TABLE app_ferias.hierarquia_gestao ADD COLUMN IF NOT EXISTS gestor_direto_matricula VARCHAR(50);
ALTER TABLE app_ferias.hierarquia_gestao ADD COLUMN IF NOT EXISTS gestor_direto_email VARCHAR(255);
ALTER TABLE app_ferias.hierarquia_gestao ADD COLUMN IF NOT EXISTS gestor_superior_matricula VARCHAR(50);

CREATE TABLE IF NOT EXISTS app_ferias.periodos_aquisitivos (
    id SERIAL PRIMARY KEY,
    colaborador_id INTEGER REFERENCES app_ferias.colaboradores(id),
    colaborador_matricula VARCHAR(50) REFERENCES app_ferias.colaboradores(matricula),
    periodo_numero INTEGER NOT NULL,
    data_inicio DATE NOT NULL,
    data_fim DATE NOT NULL,
    is_atual BOOLEAN DEFAULT FALSE,
    UNIQUE(colaborador_matricula, periodo_numero)
);
ALTER TABLE app_ferias.periodos_aquisitivos ADD COLUMN IF NOT EXISTS colaborador_matricula VARCHAR(50);
CREATE UNIQUE INDEX IF NOT EXISTS uq_periodos_matricula_numero ON app_ferias.periodos_aquisitivos (colaborador_matricula, periodo_numero);

CREATE TABLE IF NOT EXISTS app_ferias.saldos_periodo (
    id SERIAL PRIMARY KEY,
    periodo_id INTEGER REFERENCES app_ferias.periodos_aquisitivos(id) ON DELETE CASCADE,
    tipo_saldo VARCHAR(20) NOT NULL DEFAULT 'REGULAR',
    dias_direito NUMERIC(6,2) DEFAULT 0,
    dias_reservados NUMERIC(6,2) DEFAULT 0,
    dias_usados NUMERIC(6,2) DEFAULT 0,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(periodo_id, tipo_saldo)
);

CREATE TABLE IF NOT EXISTS app_ferias.solicitacoes_ferias (
    id SERIAL PRIMARY KEY,
    colaborador_id INTEGER REFERENCES app_ferias.colaboradores(id),
    colaborador_matricula VARCHAR(50) REFERENCES app_ferias.colaboradores(matricula),
    solicitante_id INTEGER REFERENCES app_ferias.colaboradores(id),
    solicitante_matricula VARCHAR(50) REFERENCES app_ferias.colaboradores(matricula),
    tipo_solicitacao VARCHAR(50),
    tipo_ferias VARCHAR(20),
    data_inicio DATE NOT NULL,
    data_fim DATE,
    dias_solicitados NUMERIC(6,2) NOT NULL DEFAULT 0,
    status VARCHAR(50) DEFAULT 'PENDENTE',
    observacoes TEXT,
    origem_sheet_id VARCHAR(50),
    smartsheet_row_id VARCHAR(50),
    colaborador_email VARCHAR(255),
    gestor_solicitante_email VARCHAR(255),
    criado_por VARCHAR(255),
    solicitacao VARCHAR(255),
    saldo_tipo VARCHAR(50) DEFAULT 'REGULAR',
    dias INTEGER,
    is_ajuste BOOLEAN DEFAULT FALSE,
    metadata JSONB,
    raw_payload JSONB,
    source_created_at TIMESTAMP,
    source_modified_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
ALTER TABLE app_ferias.solicitacoes_ferias ADD COLUMN IF NOT EXISTS colaborador_matricula VARCHAR(50);
ALTER TABLE app_ferias.solicitacoes_ferias ADD COLUMN IF NOT EXISTS solicitante_matricula VARCHAR(50);
ALTER TABLE app_ferias.solicitacoes_ferias ADD COLUMN IF NOT EXISTS colaborador_email VARCHAR(255);
ALTER TABLE app_ferias.solicitacoes_ferias ADD COLUMN IF NOT EXISTS gestor_solicitante_email VARCHAR(255);
ALTER TABLE app_ferias.solicitacoes_ferias ADD COLUMN IF NOT EXISTS criado_por VARCHAR(255);
ALTER TABLE app_ferias.solicitacoes_ferias ADD COLUMN IF NOT EXISTS solicitacao VARCHAR(255);
ALTER TABLE app_ferias.solicitacoes_ferias ADD COLUMN IF NOT EXISTS saldo_tipo VARCHAR(50) DEFAULT 'REGULAR';
ALTER TABLE app_ferias.solicitacoes_ferias ADD COLUMN IF NOT EXISTS dias INTEGER;
ALTER TABLE app_ferias.solicitacoes_ferias ADD COLUMN IF NOT EXISTS is_ajuste BOOLEAN DEFAULT FALSE;
ALTER TABLE app_ferias.solicitacoes_ferias ADD COLUMN IF NOT EXISTS metadata JSONB;
ALTER TABLE app_ferias.solicitacoes_ferias ADD COLUMN IF NOT EXISTS raw_payload JSONB;
CREATE INDEX IF NOT EXISTS ix_solicitacoes_ferias_colab_matricula ON app_ferias.solicitacoes_ferias (colaborador_matricula);

CREATE TABLE IF NOT EXISTS app_ferias.auditoria_saldos (
    id SERIAL PRIMARY KEY,
    saldo_id INTEGER REFERENCES app_ferias.saldos_periodo(id),
    usuario_alterou_id INTEGER REFERENCES app_ferias.colaboradores(id),
    usuario_alterou_matricula VARCHAR(50) REFERENCES app_ferias.colaboradores(matricula),
    data_movimento TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    tipo_movimento VARCHAR(50) NOT NULL,
    dias_anteriores NUMERIC(6,2),
    dias_alterados NUMERIC(6,2),
    dias_novos NUMERIC(6,2),
    observacoes TEXT
);
ALTER TABLE app_ferias.auditoria_saldos ADD COLUMN IF NOT EXISTS usuario_alterou_matricula VARCHAR(50);

CREATE TABLE IF NOT EXISTS app_ferias.colaborador_complemento (
    id SERIAL PRIMARY KEY,
    colaborador_id INTEGER UNIQUE NOT NULL REFERENCES app_ferias.colaboradores(id) ON DELETE CASCADE,
    colaborador_matricula VARCHAR(50) REFERENCES app_ferias.colaboradores(matricula),
    user_type VARCHAR(50) DEFAULT 'USER',
    gestor_direto_email VARCHAR(255),
    gestor_superior_email VARCHAR(255),
    ativo_no_app BOOLEAN DEFAULT TRUE,
    flags_internas JSONB,
    saldo_regular_direito INTEGER DEFAULT 0,
    saldo_regular_usado INTEGER DEFAULT 0,
    saldo_regular_reservado INTEGER DEFAULT 0,
    saldo_regular_disponivel INTEGER DEFAULT 0,
    saldo_premium_direito INTEGER DEFAULT 0,
    saldo_premium_usado INTEGER DEFAULT 0,
    saldo_premium_reservado INTEGER DEFAULT 0,
    saldo_premium_disponivel INTEGER DEFAULT 0,
    total_solicitacoes INTEGER DEFAULT 0,
    periodo_aquisitivo_atual JSONB,
    calculated_at TIMESTAMP,
    origem_sheet_id VARCHAR(50),
    origem_row_id VARCHAR(50),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
ALTER TABLE app_ferias.colaborador_complemento ADD COLUMN IF NOT EXISTS colaborador_matricula VARCHAR(50);

CREATE TABLE IF NOT EXISTS app_ferias.admin_configs (
    id SERIAL PRIMARY KEY,
    rule_type VARCHAR(100) NOT NULL,
    target_type VARCHAR(50) NOT NULL,
    target_value VARCHAR(255),
    enabled BOOLEAN DEFAULT TRUE,
    valid_from TIMESTAMP,
    valid_until TIMESTAMP,
    reason VARCHAR(500),
    config_data JSONB,
    created_by VARCHAR(255) NOT NULL,
    revoked_by VARCHAR(255),
    revoked_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS app_ferias.auditoria (
    id SERIAL PRIMARY KEY,
    actor_email VARCHAR(255) NOT NULL,
    action VARCHAR(100) NOT NULL,
    entity_type VARCHAR(50) NOT NULL,
    entity_id INTEGER NOT NULL,
    before_data JSONB,
    after_data JSONB,
    context JSONB,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS app_ferias.sync_state (
    sync_name VARCHAR(100) PRIMARY KEY,
    last_started_at TIMESTAMP,
    last_finished_at TIMESTAMP,
    last_success_at TIMESTAMP,
    last_status VARCHAR(50),
    last_error TEXT,
    extra JSONB,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


