-- Períodos e saldos consolidados de abertura
DELETE FROM app_ferias.auditoria_saldos WHERE observacoes ILIKE '%migração%' OR observacoes ILIKE '%migracao%';
DELETE FROM app_ferias.saldos_periodo;
DELETE FROM app_ferias.periodos_aquisitivos;

-- Cache de compatibilidade com saldos consolidados

SELECT setval(pg_get_serial_sequence('app_ferias.periodos_aquisitivos','id'), COALESCE((SELECT MAX(id) FROM app_ferias.periodos_aquisitivos), 1), true);
SELECT setval(pg_get_serial_sequence('app_ferias.saldos_periodo','id'), COALESCE((SELECT MAX(id) FROM app_ferias.saldos_periodo), 1), true);
SELECT setval(pg_get_serial_sequence('app_ferias.solicitacoes_ferias','id'), COALESCE((SELECT MAX(id) FROM app_ferias.solicitacoes_ferias), 1), true);
SELECT setval(pg_get_serial_sequence('app_ferias.colaborador_complemento','id'), COALESCE((SELECT MAX(id) FROM app_ferias.colaborador_complemento), 1), true);

VALUES ('migracao_v12_matricula', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 'success', jsonb_build_object('colaboradores', (SELECT COUNT(*) FROM app_ferias.colaboradores), 'solicitacoes', (SELECT COUNT(*) FROM app_ferias.solicitacoes_ferias), 'periodos', (SELECT COUNT(*) FROM app_ferias.periodos_aquisitivos), 'saldos', (SELECT COUNT(*) FROM app_ferias.saldos_periodo)), CURRENT_TIMESTAMP)
ON CONFLICT (sync_name) DO UPDATE SET last_finished_at=EXCLUDED.last_finished_at, last_success_at=EXCLUDED.last_success_at, last_status=EXCLUDED.last_status, extra=EXCLUDED.extra, updated_at=CURRENT_TIMESTAMP;

